edits.newText:
  testWidgets('mode flip updates visibility within a frame',
      (tester) async {
    SettingsService().operatingModeNotifier.value = OperatingMode.own;

    await _pumpInTallViewport(tester, _wrap(const VoidSettingsSheet()));

    expect(find.text('SOUND', skipOffstage: false), findsOneWidget);
    expect(find.text('EXTERNAL', skipOffstage: false), findsNothing);

    // Flip mode directly on the notifier — the sheet must rebuild from the
    // ValueListenableBuilder, no rebuild trigger from outside.
    SettingsService().operatingModeNotifier.value = OperatingMode.background;
    await tester.pump();

    expect(find.text('SOUND', skipOffstage: false), findsNothing);
    expect(find.text('EXTERNAL', skipOffstage: false), findsOneWidget);
  });

  testWidgets('cassette controls appear directly under screen selector',
      (tester) async {
    SettingsService().operatingModeNotifier.value = OperatingMode.own;
    await SettingsService().saveScreenConfig(const CassetteScreenConfig());

    await _pumpInTallViewport(tester, _wrap(const VoidSettingsSheet()));

    double y(String key) => tester
        .getTopLeft(find.byKey(ValueKey(key), skipOffstage: false))
        .dy;

    final yScreen = y('void-settings-screen');
    final yCassette = y('void-settings-cassette-variant');
    final yImmersive = y('void-settings-immersive');

    expect(yCassette > yScreen, isTrue,
        reason: 'Cassette variant should be rendered immediately below the screen row');
    expect(yImmersive > yCassette, isTrue,
        reason: 'Cassette controls should appear before the immersive toggle');
  });
});

